export type IconName = keyof typeof PATHS;

export function Icon({ name, size = 20, stroke = 2, className, label }: { name: IconName; size?: number; stroke?: number; className?: string; label?: string }) {
  const filled = FILLED[name];
  if (filled) {
    return (
      <svg className={className} width={size} height={size} viewBox={filled.viewBox} fill="currentColor"
        role={label ? "img" : undefined} aria-label={label} aria-hidden={label ? undefined : true}>
        <path d={filled.d} />
      </svg>
    );
  }
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={stroke}
      strokeLinecap="round"
      strokeLinejoin="round"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
    >
      <path d={PATHS[name]} />
    </svg>
  );
}
